#!/usr/bin/env bash\nset -euo pipefail\n\ncd \"$(dirname \"$0\")\"\n\necho \"================================================\"\necho \"KETTLE: Complete Automated x402 Setup\"\necho \"================================================\"\necho \"\"\n\n# Color codes\nGREEN='\\033[0;32m'\nBLUE='\\033[0;34m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color\n\ninfo() { echo -e \"${BLUE}[SETUP]${NC} $1\"; }\nsuccess() { echo -e \"${GREEN}[SUCCESS]${NC} $1\"; }\nwarn() { echo -e \"${YELLOW}[WARN]${NC} $1\"; }\nerror() { echo -e \"${RED}[ERROR]${NC} $1\"; exit 1; }\n\n# Step 1: Check Node\ninfo \"Checking Node.js...\"\nif ! command -v node &> /dev/null; then\n    error \"Node.js not found. Install Node 20+ from https://nodejs.org\"\nfi\nNODE_VERSION=$(node --version)\nsuccess \"Node.js $NODE_VERSION found\"\n\n# Step 2: Install dependencies\ninfo \"Installing npm dependencies...\"\nnpm install --silent 2>/dev/null || true\nsuccess \"Dependencies installed\"\n\n# Step 3: Check/Install Wrangler\ninfo \"Checking Wrangler...\"\nif ! npx wrangler --version &> /dev/null; then\n    warn \"Wrangler not found, installing...\"\n    npm install --save-dev wrangler@latest --silent\nfi\nWRANGLER_VERSION=$(npx wrangler --version 2>/dev/null | head -1)\nsuccess \"Wrangler $WRANGLER_VERSION ready\"\n\n# Step 4: Environment setup\necho \"\"\ninfo \"Setting up environment variables...\"\n\nif [ ! -f \".env.production\" ]; then\n    cat > .env.production << 'EOF'\n# KETTLE x402 Production Configuration\n\n# === BASE MAINNET WALLET ===\n# Your Base wallet private key (for receiving USDC payments)\n# DO NOT COMMIT THIS FILE\nBASE_PRIVATE_KEY=\n\n# Your Base wallet address (public, safe to share)\nBASE_WALLET_ADDRESS=\n\n# === USDC CONTRACT ===\n# USDC on Base mainnet (do not change)\nUSDC_CONTRACT_BASE=0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913\n\n# === RPC ===\n# Base mainnet RPC endpoint\nBASE_RPC_URL=https://mainnet.base.org\n\n# === PRICING ===\n# Fee in USDC (microunits, 6 decimals)\n# 0.005 USDC = 5000\n# 0.001 USDC = 1000\nFEE_AMOUNT_USDC=5000\n\n# === TELEGRAM (Optional) ===\n# Get token from @BotFather on Telegram\nTELEGRAM_BOT_TOKEN=\n\n# Your Telegram user ID (for admin commands)\n# Get it: https://t.me/userinfobot\nTELEGRAM_ADMIN_ID=\n\n# === CLOUDFLARE ===\n# Your Cloudflare account ID\nCLOUDFLARE_ACCOUNT_ID=\n\n# === GITHUB ===\n# GitHub personal access token (for storing revenue data)\nGITHUB_TOKEN=\n\n# === DEPLOYMENT ===\nWORKER_NAME=kettle\nWORKER_ROUTE=kettle.example.com/*\nENVIRONMENT=production\nEOF\n    \n    success \"Created .env.production (edit with your values)\"\nelse\n    warn \".env.production already exists\"\nfi\n\n# Step 5: Get Base wallet info\necho \"\"\ninfo \"Configuring Base mainnet wallet...\"\necho \"\"\necho \"You need:\"\necho \"  1. A Base mainnet wallet (MetaMask, Coinbase Wallet, etc.)\"\necho \"  2. Some USDC or ETH to receive payments\"\necho \"\"\necho \"To get your wallet:\"\necho \"  1. Go to metamask.io or wallet.coinbase.com\"\necho \"  2. Create/import wallet\"\necho \"  3. Switch to Base mainnet network\"\necho \"  4. Copy your address (starts with 0x...)\"\necho \"\"\nread -p \"Enter your Base wallet address (0x...): \" BASE_ADDR\nif [[ ! $BASE_ADDR =~ ^0x[a-fA-F0-9]{40}$ ]]; then\n    error \"Invalid Base address format\"\nfi\n\nsed -i.bak \"s/BASE_WALLET_ADDRESS=.*/BASE_WALLET_ADDRESS=$BASE_ADDR/\" .env.production\nsuccess \"Wallet address set: $BASE_ADDR\"\n\n# Step 6: Telegram token (optional)\necho \"\"\ninfo \"Telegram bot setup (optional - for notifications)...\"\nread -p \"Enter Telegram bot token (or press Enter to skip): \" TG_TOKEN\nif [ ! -z \"$TG_TOKEN\" ]; then\n    sed -i.bak \"s/TELEGRAM_BOT_TOKEN=.*/TELEGRAM_BOT_TOKEN=$TG_TOKEN/\" .env.production\n    read -p \"Enter your Telegram user ID: \" TG_ID\n    sed -i.bak \"s/TELEGRAM_ADMIN_ID=.*/TELEGRAM_ADMIN_ID=$TG_ID/\" .env.production\n    success \"Telegram bot configured\"\nelse\n    warn \"Skipping Telegram (you can add it later)\"\nfi\n\n# Step 7: Create wrangler.toml\ninfo \"Creating wrangler.toml...\"\ncat > wrangler.toml << 'EOF'\nname = \"kettle\"\nmain = \"src/index.js\"\ncompatibility_date = \"2025-07-01\"\ncompatibility_flags = [\"nodejs_compat\"]\n\n[env.production]\nvars = { ENV = \"production\", APP_VERSION = \"1.0.0\" }\n\n[env.development]\nvars = { ENV = \"development\", APP_VERSION = \"1.0.0-dev\" }\nEOF\nsuccess \"wrangler.toml created\"\n\n# Step 8: Create GitHub revenue tracking\ninfo \"Setting up GitHub revenue tracking...\"\nmkdir -p data/revenue\ntouch data/revenue/.gitkeep\ncat > data/README.md << 'EOF'\n# KETTLE Revenue Data\n\nAll verified x402 payments are recorded here.\n\n## Structure\n\n- `revenue/` - Payment records (immutable ledger)\n- `stats.json` - Aggregated statistics\n\n## Privacy\n\nThis data is public and transparent.\nEvery payment is cryptographically verified on Base blockchain.\nEOF\nsuccess \"Revenue tracking directory created\"\n\n# Step 9: Create dashboard HTML\ninfo \"Creating profit dashboard...\"\nmkdir -p docs\ncat > docs/index.html << 'EOF'\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>KETTLE - x402 Revenue Dashboard</title>\n    <style>\n        * { margin: 0; padding: 0; box-sizing: border-box; }\n        body {\n            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;\n            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n            min-height: 100vh;\n            padding: 20px;\n        }\n        .container {\n            max-width: 1200px;\n            margin: 0 auto;\n        }\n        .header {\n            text-align: center;\n            color: white;\n            margin-bottom: 40px;\n        }\n        .header h1 {\n            font-size: 2.5em;\n            margin-bottom: 10px;\n            text-shadow: 2px 2px 4px rgba(0,0,0,0.3);\n        }\n        .header p {\n            font-size: 1.1em;\n            opacity: 0.9;\n        }\n        .stats {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n            gap: 20px;\n            margin-bottom: 30px;\n        }\n        .stat-card {\n            background: white;\n            border-radius: 12px;\n            padding: 25px;\n            box-shadow: 0 10px 30px rgba(0,0,0,0.2);\n            transition: transform 0.3s, box-shadow 0.3s;\n        }\n        .stat-card:hover {\n            transform: translateY(-5px);\n            box-shadow: 0 15px 40px rgba(0,0,0,0.3);\n        }\n        .stat-label {\n            font-size: 0.9em;\n            color: #666;\n            text-transform: uppercase;\n            letter-spacing: 1px;\n            margin-bottom: 10px;\n        }\n        .stat-value {\n            font-size: 2.5em;\n            font-weight: bold;\n            color: #667eea;\n            font-family: 'Courier New', monospace;\n        }\n        .stat-unit {\n            font-size: 0.6em;\n            color: #999;\n            margin-left: 5px;\n        }\n        .chart {\n            background: white;\n            border-radius: 12px;\n            padding: 25px;\n            box-shadow: 0 10px 30px rgba(0,0,0,0.2);\n            margin-bottom: 30px;\n        }\n        .chart h2 {\n            margin-bottom: 20px;\n            color: #333;\n        }\n        .transactions {\n            background: white;\n            border-radius: 12px;\n            padding: 25px;\n            box-shadow: 0 10px 30px rgba(0,0,0,0.2);\n        }\n        .transactions h2 {\n            margin-bottom: 20px;\n            color: #333;\n        }\n        .tx-item {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            padding: 15px;\n            border-bottom: 1px solid #eee;\n            font-family: 'Courier New', monospace;\n            font-size: 0.9em;\n        }\n        .tx-item:last-child {\n            border-bottom: none;\n        }\n        .tx-hash {\n            color: #667eea;\n            word-break: break-all;\n        }\n        .tx-amount {\n            font-weight: bold;\n            color: #27ae60;\n        }\n        .loading {\n            text-align: center;\n            color: white;\n            font-size: 1.2em;\n        }\n        .error {\n            background: #e74c3c;\n            color: white;\n            padding: 15px;\n            border-radius: 8px;\n            text-align: center;\n            margin-bottom: 20px;\n        }\n        .success {\n            background: #27ae60;\n            color: white;\n            padding: 15px;\n            border-radius: 8px;\n            text-align: center;\n            margin-bottom: 20px;\n        }\n        .refresh {\n            text-align: center;\n            margin-top: 20px;\n        }\n        .refresh button {\n            background: #667eea;\n            color: white;\n            border: none;\n            padding: 12px 30px;\n            border-radius: 6px;\n            font-size: 1em;\n            cursor: pointer;\n            transition: background 0.3s;\n        }\n        .refresh button:hover {\n            background: #5568d3;\n        }\n        .footer {\n            text-align: center;\n            color: white;\n            margin-top: 40px;\n            opacity: 0.8;\n        }\n        .footer a {\n            color: white;\n            text-decoration: none;\n            border-bottom: 1px solid white;\n        }\n        .badge {\n            display: inline-block;\n            background: #27ae60;\n            color: white;\n            padding: 4px 12px;\n            border-radius: 20px;\n            font-size: 0.8em;\n            margin-left: 10px;\n        }\n    </style>\n</head>\n<body>\n    <div class=\"container\">\n        <div class=\"header\">\n            <h1>⚡ KETTLE</h1>\n            <p>x402 URL Checking API - Real-Time Revenue Dashboard</p>\n        </div>\n\n        <div id=\"status\"></div>\n\n        <div class=\"stats\">\n            <div class=\"stat-card\">\n                <div class=\"stat-label\">Total Revenue</div>\n                <div class=\"stat-value\">\n                    <span id=\"total-revenue\">0</span>\n                    <span class=\"stat-unit\">USDC</span>\n                </div>\n            </div>\n            <div class=\"stat-card\">\n                <div class=\"stat-label\">Total Checks</div>\n                <div class=\"stat-value\">\n                    <span id=\"total-checks\">0</span>\n                    <span class=\"stat-unit\">requests</span>\n                </div>\n            </div>\n            <div class=\"stat-card\">\n                <div class=\"stat-label\">Verified Payments</div>\n                <div class=\"stat-value\">\n                    <span id=\"verified-payments\">0</span>\n                    <span class=\"stat-unit\">txs</span>\n                </div>\n            </div>\n            <div class=\"stat-card\">\n                <div class=\"stat-label\">This Month</div>\n                <div class=\"stat-value\">\n                    <span id=\"month-revenue\">0</span>\n                    <span class=\"stat-unit\">USDC</span>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"transactions\">\n            <h2>Recent Transactions</h2>\n            <div id=\"transactions-list\" class=\"loading\">Loading transactions...</div>\n        </div>\n\n        <div class=\"refresh\">\n            <button onclick=\"location.reload()\">🔄 Refresh Data</button>\n        </div>\n\n        <div class=\"footer\">\n            <p>KETTLE x402 API • <a href=\"https://github.com/phalanejay-alt/kettle\" target=\"_blank\">GitHub</a> • Base Mainnet • Automated Payments</p>\n        </div>\n    </div>\n\n    <script>\n        async function loadStats() {\n            try {\n                // Fetch from GitHub API\n                const response = await fetch('https://api.github.com/repos/phalanejay-alt/kettle/contents/data/revenue');\n                \n                if (!response.ok) {\n                    document.getElementById('status').innerHTML = '<div class=\"error\">Unable to load data. Make sure revenue files are committed to GitHub.</div>';\n                    return;\n                }\n\n                const files = await response.json();\n                let totalRevenue = 0;\n                let totalChecks = 0;\n                let transactions = [];\n\n                // Process each revenue file\n                for (const file of files) {\n                    if (!file.name.endsWith('.json')) continue;\n\n                    const fileResponse = await fetch(file.download_url);\n                    const data = await fileResponse.json();\n\n                    if (data.kind === 'revenue' && data.status === 'VERIFIED') {\n                        totalRevenue += data.amount || 0;\n                        totalChecks += data.checks_count || 1;\n                        \n                        transactions.push({\n                            hash: data.tx_hash,\n                            amount: data.amount,\n                            date: new Date(data.created_at),\n                            verified: true\n                        });\n                    }\n                }\n\n                // Sort by date descending\n                transactions.sort((a, b) => b.date - a.date);\n\n                // Calculate month revenue\n                const now = new Date();\n                const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);\n                const monthRevenue = transactions\n                    .filter(tx => tx.date >= monthStart)\n                    .reduce((sum, tx) => sum + tx.amount, 0);\n\n                // Update display\n                document.getElementById('total-revenue').innerText = totalRevenue.toFixed(2);\n                document.getElementById('total-checks').innerText = totalChecks.toLocaleString();\n                document.getElementById('verified-payments').innerText = transactions.length;\n                document.getElementById('month-revenue').innerText = monthRevenue.toFixed(2);\n\n                // Display transactions\n                const txList = document.getElementById('transactions-list');\n                if (transactions.length === 0) {\n                    txList.innerHTML = '<p style=\"color: #999; text-align: center;\">No verified payments yet. Deploy and share your API!</p>';\n                } else {\n                    txList.innerHTML = transactions.slice(0, 20).map(tx => `\n                        <div class=\"tx-item\">\n                            <div>\n                                <div class=\"tx-hash\">0x${tx.hash.slice(2, 18)}...${tx.hash.slice(-8)}</div>\n                                <div style=\"color: #999; font-size: 0.8em;\">${tx.date.toLocaleString()}</div>\n                            </div>\n                            <div class=\"tx-amount\">+${tx.amount.toFixed(4)} USDC</div>\n                        </div>\n                    `).join('');\n                }\n\n                document.getElementById('status').innerHTML = '<div class=\"success\">✅ Dashboard synced with Base mainnet</div>';\n            } catch (error) {\n                console.error('Error loading stats:', error);\n                document.getElementById('status').innerHTML = '<div class=\"error\">⚠️ Error loading dashboard data</div>';\n            }\n        }\n\n        // Load on page load\n        loadStats();\n\n        // Refresh every 30 seconds\n        setInterval(loadStats, 30000);\n    </script>\n</body>\n</html>\nEOF\nsuccess \"Dashboard created at docs/index.html\"\n\n# Step 10: Enable GitHub Pages\ninfo \"Enabling GitHub Pages...\"\necho \"\"\necho \"Next steps:\"\necho \"  1. Push to GitHub: git add -A && git commit -m 'Setup KETTLE x402' && git push\"\necho \"  2. Go to: https://github.com/phalanejay-alt/kettle/settings/pages\"\necho \"  3. Set Source to 'Deploy from a branch'\"\necho \"  4. Select 'main' branch and '/docs' folder\"\necho \"  5. Your dashboard will be at: https://phalanejay-alt.github.io/kettle/\"\necho \"\"\n\n# Step 11: Create Wrangler secrets setup script\ninfo \"Creating secrets setup script...\"\ncat > setup-secrets.sh << 'EOF'\n#!/usr/bin/env bash\nset -euo pipefail\n\necho \"Setting Cloudflare Worker Secrets...\"\necho \"\"\n\nread -p \"Enter your Base wallet address (0x...): \" BASE_ADDR\nnpx wrangler secret put BASE_WALLET_ADDRESS --text \"$BASE_ADDR\"\n\nread -p \"Enter USDC contract (or press Enter for Base default): \" USDC_CONTRACT\nUSDC_CONTRACT=${USDC_CONTRACT:-0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913}\nnpx wrangler secret put USDC_CONTRACT_BASE --text \"$USDC_CONTRACT\"\n\nread -p \"Enter Base mainnet RPC URL (or press Enter for default): \" BASE_RPC\nBASE_RPC=${BASE_RPC:-https://mainnet.base.org}\nnpx wrangler secret put BASE_RPC_URL --text \"$BASE_RPC\"\n\nread -p \"Enter fee amount in microunits (5000 = 0.005 USDC): \" FEE_AMOUNT\nnpx wrangler secret put FEE_AMOUNT_USDC --text \"$FEE_AMOUNT\"\n\necho \"\"\necho \"✅ All secrets configured!\"\necho \"\"\necho \"Next: Deploy with 'wrangler deploy'\"\nEOF\nchmod +x setup-secrets.sh\nsuccess \"Secrets setup script created (setup-secrets.sh)\"\n\n# Step 12: Deploy\necho \"\"\ninfo \"Ready to deploy!\"\necho \"\"\necho \"${BLUE}NEXT STEPS:${NC}\"\necho \"\"\necho \"1. Configure your secrets:\"\necho \"   ${YELLOW}./setup-secrets.sh${NC}\"\necho \"\"\necho \"2. Deploy to Cloudflare:\"\necho \"   ${YELLOW}npx wrangler deploy${NC}\"\necho \"\"\necho \"3. Push to GitHub:\"\necho \"   ${YELLOW}git add -A && git commit -m 'Deploy KETTLE x402' && git push${NC}\"\necho \"\"\necho \"4. View your dashboard:\"\necho \"   ${YELLOW}https://phalanejay-alt.github.io/kettle/${NC}\"\necho \"\"\necho \"5. Share your API endpoint from Wrangler output\"\necho \"\"\necho \"${GREEN}✅ Setup complete!${NC}\"\necho \"\"\n"